import{_ as a,o as i,c as s,a4 as t}from"./chunks/framework.DCsBdTIw.js";const k=JSON.parse('{"title":"Quick Start","description":"clice implements the Language Server Protocol. Any editor that supports this protocol can work with clice to provide features like code completion, diagnostics, hover, semantic highlighting, and more.","frontmatter":{"head":[["meta",{"property":"og:title","content":"Quick Start | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/clice/guide/quick-start"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/clice/guide/quick-start"}],["meta",{"name":"twitter:card","content":"summary"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/clice/guide/quick-start"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/clice/guide/quick-start"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/clice/guide/quick-start"}],["meta",{"property":"og:description","content":"clice implements the Language Server Protocol. Any editor that supports this protocol can work with clice to provide features like code completion, diagnostics, hover, semantic highlighting, and more."}]]},"headers":[],"relativePath":"clice/guide/quick-start.md","filePath":"en/clice/guide/quick-start.md","lastUpdated":1795871266000}'),o={name:"clice/guide/quick-start.md"};function n(l,e,r,h,p,d){return i(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="quick-start" tabindex="-1">Quick Start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick Start&quot;">​</a></h1><h2 id="editor-plugins" tabindex="-1">Editor Plugins <a class="header-anchor" href="#editor-plugins" aria-label="Permalink to &quot;Editor Plugins&quot;">​</a></h2><p>clice implements the <a href="https://microsoft.github.io/language-server-protocol" target="_blank" rel="noreferrer">Language Server Protocol</a>. Any editor that supports this protocol can work with clice to provide features like <code>code completion</code>, <code>diagnostics</code>, <code>hover</code>, <code>semantic highlighting</code>, and more.</p><p>Beyond the standard protocol, clice also supports some protocol extensions. For better integration, using a dedicated clice plugin is recommended.</p><p>See <a href="./editors">Editor Setup</a> for per-editor instructions: official plugins for Visual Studio Code, Neovim and Zed, plus configuration snippets for editors with generic LSP clients (Helix, Emacs, Sublime Text, Kate, Vim).</p><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><h3 id="download-prebuilt-binary" tabindex="-1">Download Prebuilt Binary <a class="header-anchor" href="#download-prebuilt-binary" aria-label="Permalink to &quot;Download Prebuilt Binary&quot;">​</a></h3><p>Download the latest binary from the <a href="https://github.com/clice-io/clice/releases" target="_blank" rel="noreferrer">Releases</a> page.</p><p>On Linux, the <code>linux-gnu</code> packages need glibc 2.17 or newer. The <code>linux-musl</code> ones are static programs, which run on any Linux: on Alpine and other musl systems, and on NixOS and Guix without patching.</p><h3 id="build-from-source" tabindex="-1">Build from Source <a class="header-anchor" href="#build-from-source" aria-label="Permalink to &quot;Build from Source&quot;">​</a></h3><p>See <a href="./build">build from source</a> for detailed instructions.</p><h2 id="project-setup" tabindex="-1">Project Setup <a class="header-anchor" href="#project-setup" aria-label="Permalink to &quot;Project Setup&quot;">​</a></h2><p>For clice to correctly understand your code (e.g., find header file locations), you need to provide a <code>compile_commands.json</code> file, also known as a <a href="https://clang.llvm.org/docs/JSONCompilationDatabase.html" target="_blank" rel="noreferrer">compilation database</a>. The compilation database provides compilation options for each source file.</p><p>By default, clice loads every <code>compile_commands.json</code> in the project&#39;s root directory and its immediate subdirectories (e.g. <code>build/</code>), and those in the directories between a file you open and the root, so a database deeper in the tree loads the first time a file in its directory, or below it, is opened. A subdirectory with a <code>clice.toml</code>, <code>.clice/clice.toml</code> or <code>.clice/clice.local.toml</code> of its own is a separate project, whose databases the outer one never loads. This discovery turns off as soon as any rule sets <code>compile_commands</code> or <code>default_command</code>. The <a href="./config-guide#compile-commands">Configuration Guide</a> shows how to name the databases in <code>clice.toml</code>, and how to compile files that have no database entry.</p><h3 id="cmake" tabindex="-1">CMake <a class="header-anchor" href="#cmake" aria-label="Permalink to &quot;CMake&quot;">​</a></h3><p>Add <code>-DCMAKE_EXPORT_COMPILE_COMMANDS=ON</code> during configuration:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -B</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -DCMAKE_EXPORT_COMPILE_COMMANDS=ON</span></span></code></pre></div><p>This generates <code>compile_commands.json</code> in the <code>build</code> directory.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>This option only works with Makefile and Ninja generators. For other generators (e.g., Visual Studio), use an alternative approach below.</p></div><h3 id="bazel" tabindex="-1">Bazel <a class="header-anchor" href="#bazel" aria-label="Permalink to &quot;Bazel&quot;">​</a></h3><p>Use the <code>compdb</code> module of clice&#39;s Bazel registry. Add the registry and the module to the project:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># .bazelrc</span></span>
<span class="line"><span>common --registry=https://bcr.bazel.build/</span></span>
<span class="line"><span>common --registry=https://bazel.clice.io/</span></span></code></pre></div><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># MODULE.bazel</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">bazel_dep(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">name</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;compdb&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">version</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;0.1.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">dev_dependency</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> True</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>Then write <code>compile_commands.json</code> beside <code>MODULE.bazel</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bazel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @compdb//:refresh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output_groups=+compilation_prerequisites_INTERNAL_</span></span></code></pre></div><p>It covers <code>//...</code>; targets after <code>--</code> narrow it. The added output group builds what the commands read but do not build: the generated headers and the <code>_virtual_includes</code> directories through which Bazel exposes a library&#39;s headers. Without it, those headers are missing until something else builds them, and every file including them reports them not found.</p><h3 id="visual-studio" tabindex="-1">Visual Studio <a class="header-anchor" href="#visual-studio" aria-label="Permalink to &quot;Visual Studio&quot;">​</a></h3><p>For CMake projects in Visual Studio (2019 16.1+), configure in <code>CMakeSettings.json</code>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;configurations&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;x64-Debug&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;generator&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Ninja&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;buildRoot&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;\${projectDir}</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\\\</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">build&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;cmakeCommandArgs&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;-DCMAKE_EXPORT_COMPILE_COMMANDS=ON&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>For MSBuild projects (<code>.vcxproj</code>), use <a href="https://github.com/clice-io/catter" target="_blank" rel="noreferrer">catter</a> to generate the compilation database.</p><h3 id="makefile" tabindex="-1">Makefile <a class="header-anchor" href="#makefile" aria-label="Permalink to &quot;Makefile&quot;">​</a></h3><p>Use <a href="https://github.com/rizsotto/Bear" target="_blank" rel="noreferrer">bear</a> to intercept compilation commands:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bear</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> make</span></span></code></pre></div><p>Run <code>make clean</code> before <code>bear -- make</code> to ensure all commands are captured.</p><h3 id="meson" tabindex="-1">Meson <a class="header-anchor" href="#meson" aria-label="Permalink to &quot;Meson&quot;">​</a></h3><p>Meson generates a compilation database automatically:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">meson</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><h3 id="xmake" tabindex="-1">Xmake <a class="header-anchor" href="#xmake" aria-label="Permalink to &quot;Xmake&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">xmake</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> project</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -k</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compile_commands</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --lsp=clangd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p>Or configure the Xmake VS Code extension to auto-generate:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;xmake.compileCommandsDirectory&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;build&quot;</span></span></code></pre></div><h3 id="others" tabindex="-1">Others <a class="header-anchor" href="#others" aria-label="Permalink to &quot;Others&quot;">​</a></h3><p>For any other build system, use <a href="https://github.com/clice-io/catter" target="_blank" rel="noreferrer">catter</a> — a fake-compiler approach that works with any build system.</p><h2 id="pre-build-the-index-optional" tabindex="-1">Pre-build the Index (Optional) <a class="header-anchor" href="#pre-build-the-index-optional" aria-label="Permalink to &quot;Pre-build the Index (Optional)&quot;">​</a></h2><p>Background indexing starts automatically when you open the project in an editor. For large projects you can also build the index ahead of time from the command line:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">clice</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> index</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --workspace</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/project</span></span></code></pre></div><p>The run is resumable — interrupting it with Ctrl-C saves progress, and the next invocation continues where it left off instead of starting over. <code>clice index stats --workspace /path/to/project</code> prints what the persisted index contains. <a href="./config-guide#a-faster-first-index">A Faster First Index</a> says how to make the first one take less time.</p>`,47)])])}const u=a(o,[["render",n]]);export{k as __pageData,u as default};
